"""Export the catalogue as CSV text."""
import csv
import io

from shelf import books


def dump(author=None):
    out = io.StringIO()
    writer = csv.writer(out)
    writer.writerow(["title", "author"])
    for b in books.all_books():
        if author is None or b["author"] == author:
            writer.writerow([b["title"], b["author"]])
    return out.getvalue()

import csv
import io

from shelf import books, export


def setup_function():
    books.clear()


def _rows(text):
    return list(csv.reader(io.StringIO(text)))


def test_empty_shelf_header_only():
    assert _rows(export.dump()) == [["title", "author"]]


def test_title_with_comma_and_quote_round_trips():
    books.add('Hello, "World"', "A. Writer")
    assert _rows(export.dump()) == [["title", "author"], ['Hello, "World"', "A. Writer"]]


def test_author_filter():
    books.add("Dune", "Frank Herbert")
    books.add("Emma", "Jane Austen")
    assert _rows(export.dump(author="Jane Austen")) == [["title", "author"], ["Emma", "Jane Austen"]]
    assert len(_rows(export.dump())) == 3
